import{_ as t,o as r,c as o,a2 as i}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"Filtering, Sorting, Grouping","description":"Filter, sort, and group entries in a view — including filter groups and aggregates.","frontmatter":{"title":"Filtering, Sorting, Grouping","description":"Filter, sort, and group entries in a view — including filter groups and aggregates."},"headers":[],"relativePath":"en/ansichten/filtern-sortieren-gruppieren.md","filePath":"en/ansichten/filtern-sortieren-gruppieren.md","lastUpdated":1787319236000}'),a={name:"en/ansichten/filtern-sortieren-gruppieren.md"};function n(s,e,l,d,h,g){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="filtering-sorting-grouping" tabindex="-1">Filtering, Sorting, Grouping <a class="header-anchor" href="#filtering-sorting-grouping" aria-label="Permalink to &quot;Filtering, Sorting, Grouping&quot;">​</a></h1><p>These three tools determine which entries in a view are visible and how they&#39;re arranged. All three apply <strong>only to the current view</strong> — other views of the same Grid remain unaffected.</p><h2 id="filtering" tabindex="-1">Filtering <a class="header-anchor" href="#filtering" aria-label="Permalink to &quot;Filtering&quot;">​</a></h2><p>A filter determines which entries are visible. The interface phrases this as <em>In this view, show entries …</em>.</p><h3 id="creating-a-filter" tabindex="-1">Creating a filter <a class="header-anchor" href="#creating-a-filter" aria-label="Permalink to &quot;Creating a filter&quot;">​</a></h3><ol><li>Click <strong>Filter</strong> in the toolbar.</li><li>Choose <strong>Add filter</strong>.</li><li>Choose <strong>Field</strong>, <strong>Condition</strong>, and <strong>Value</strong>.</li></ol><p>Example: <code>Status</code> <code>equals</code> <code>Open</code>.</p><h3 id="available-conditions" tabindex="-1">Available conditions <a class="header-anchor" href="#available-conditions" aria-label="Permalink to &quot;Available conditions&quot;">​</a></h3><p>Which conditions are available depends on the column type:</p><table tabindex="0"><thead><tr><th>Condition</th><th>Available for</th></tr></thead><tbody><tr><td>equals / does not equal</td><td>most types</td></tr><tr><td>contains / does not contain</td><td>text-like types</td></tr><tr><td>is less than / is greater than</td><td>Number, Decimal, Currency</td></tr><tr><td>is before / is after</td><td>Date, Date and time</td></tr><tr><td>contains any of / none of / all of</td><td>Multiple Select, multi-link</td></tr><tr><td>is / is not</td><td>User, Created by</td></tr><tr><td>is empty / is not empty</td><td>almost all types</td></tr></tbody></table><p>The complete mapping is in <a href="/en/referenz/filterbedingungen">Filter conditions</a>.</p><h3 id="relative-values" tabindex="-1">Relative values <a class="header-anchor" href="#relative-values" aria-label="Permalink to &quot;Relative values&quot;">​</a></h3><p>For date fields, you can choose a relative expression instead of a fixed date:</p><ul><li><strong>today</strong>, <strong>tomorrow</strong>, <strong>yesterday</strong></li><li><strong>X days ago</strong>, <strong>in X days</strong></li><li><strong>exact date</strong></li></ul><p>For fields tied to people, <strong>logged-in user</strong> is available.</p><p>Behind this are <a href="/en/apptivescript/was-ist-apptivescript">ApptiveScript</a> expressions: <em>today</em> is <code>today()</code>, <em>7 days ago</em> is <code>today().subtractDays(7)</code>. You never see this — the filter dialog writes it for you.</p><div class="tip custom-block"><p class="custom-block-title">Personal views without duplicates</p><p>The combination <code>Assignee</code> <code>is</code> <code>logged-in user</code> creates a view that automatically shows each person their own entries. You don&#39;t need a separate view per team member.</p></div><h3 id="filter-groups" tabindex="-1">Filter groups <a class="header-anchor" href="#filter-groups" aria-label="Permalink to &quot;Filter groups&quot;">​</a></h3><p>Combine multiple conditions via <strong>Add filter group</strong> with <strong>and</strong> or <strong>or</strong>:</p><ul><li><strong>and</strong> — <em>All of the following conditions match</em></li><li><strong>or</strong> — <em>One of the following conditions matches</em></li></ul><p>Groups can be nested to express things like &quot;A and (B or C).&quot;</p><div class="warning custom-block"><p class="custom-block-title">Up to three levels of nesting</p><p>ApptiveGrid allows a maximum of three levels and otherwise reports <em>Filter conditions can only be nested 3 levels deep</em>.</p><p>If you need more, a helper field is usually the better solution: create a field of type <strong>Formula</strong> or <strong>Checkmark</strong> that represents the complex condition, and filter on that.</p></div><h3 id="incomplete-filters" tabindex="-1">Incomplete filters <a class="header-anchor" href="#incomplete-filters" aria-label="Permalink to &quot;Incomplete filters&quot;">​</a></h3><p>As long as a condition is incomplete, ApptiveGrid reports <em>All existing filters must be valid</em> and doesn&#39;t apply the filter. Complete or remove the condition.</p><h3 id="saved-and-temporary-filters" tabindex="-1">Saved and temporary filters <a class="header-anchor" href="#saved-and-temporary-filters" aria-label="Permalink to &quot;Saved and temporary filters&quot;">​</a></h3><p>There are two kinds:</p><table tabindex="0"><thead><tr><th>Kind</th><th>Behavior</th></tr></thead><tbody><tr><td><strong>Saved filter</strong></td><td>Part of the view. Applies to everyone who sees this view — including shared links.</td></tr><tr><td><strong>Temporary filter</strong></td><td>Only for you and only for this session. The interface calls this <em>Search and filter entries (temporary)</em>.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Try temporary first</p><p>If you&#39;re working in a view colleagues also use, use the temporary filter. A saved filter changes the view for everyone.</p></div><h3 id="row-filtered" tabindex="-1">&quot;Row filtered&quot; <a class="header-anchor" href="#row-filtered" aria-label="Permalink to &quot;&quot;Row filtered&quot;&quot;">​</a></h3><p>If you edit an entry so it no longer matches the filter, ApptiveGrid reports <strong>Row filtered</strong> and hides it. The entry isn&#39;t deleted — it just no longer meets the filter condition, and it still exists in an unfiltered view.</p><h2 id="sorting" tabindex="-1">Sorting <a class="header-anchor" href="#sorting" aria-label="Permalink to &quot;Sorting&quot;">​</a></h2><p>Sorting determines the order of entries.</p><ol><li>Click <strong>Sort</strong>.</li><li>Choose a field and a direction.</li><li>Add further fields if needed — they apply as tiebreakers.</li></ol><p>Example: first by <code>Priority</code> descending, then by <code>Due date</code> ascending.</p><h2 id="grouping" tabindex="-1">Grouping <a class="header-anchor" href="#grouping" aria-label="Permalink to &quot;Grouping&quot;">​</a></h2><p>Grouping bundles entries by the values of a field. Each group gets a header row and can be expanded and collapsed.</p><p>Fields of type <strong>Single Select</strong>, <strong>Checkmark</strong>, <strong>User</strong>, and <strong>Link record</strong> work especially well.</p><h3 id="aggregates" tabindex="-1">Aggregates <a class="header-anchor" href="#aggregates" aria-label="Permalink to &quot;Aggregates&quot;">​</a></h3><p>Per group, you can display a metric:</p><table tabindex="0"><thead><tr><th>Aggregate</th><th>Meaning</th><th>Useful for</th></tr></thead><tbody><tr><td><strong>Sum</strong></td><td>sum of all values</td><td>Number, Decimal, Currency</td></tr><tr><td><strong>Average</strong></td><td>mean value</td><td>Number, Decimal, Currency</td></tr><tr><td><strong>Minimum</strong></td><td>smallest value</td><td>numeric types, Date</td></tr><tr><td><strong>Maximum</strong></td><td>largest value</td><td>numeric types, Date</td></tr><tr><td><strong>Filled</strong></td><td>count of entries with a value</td><td>all types</td></tr><tr><td><strong>Empty</strong></td><td>count of entries without a value</td><td>all types</td></tr><tr><td><strong>Checked</strong></td><td>count of set checkmarks</td><td>Checkmark</td></tr><tr><td><strong>Unchecked</strong></td><td>count of unset checkmarks</td><td>Checkmark</td></tr><tr><td><strong>None</strong></td><td>no metric</td><td>–</td></tr></tbody></table><p>You choose the aggregate <strong>directly in a group&#39;s footer row</strong>: clicking the value under a column opens the picker, with the active aggregate marked with a checkmark.</p><div class="tip custom-block"><p class="custom-block-title">A separate aggregate per column</p><p>The setting applies per column, not to the whole group. In a view grouped by customer, you can therefore show the <strong>sum</strong> of amounts, the <strong>average</strong> of durations, and the <strong>count</strong> of filled-in notes fields all at the same time.</p></div><div class="tip custom-block"><p class="custom-block-title">Analysis without a chart</p><p>Grouping with sum is the fastest route to a report: &quot;Revenue by customer&quot; is a grouping by customer with the sum of the amount field — no additional tool needed.</p></div><h2 id="sum-row" tabindex="-1">Sum row <a class="header-anchor" href="#sum-row" aria-label="Permalink to &quot;Sum row&quot;">​</a></h2><p>Below numeric columns you can display a <strong>sum</strong> across all visible entries. It respects the active filter.</p><p>Available for <strong>Number</strong>, <strong>Decimal</strong>, and <strong>Currency</strong>.</p><h2 id="how-they-interact" tabindex="-1">How they interact <a class="header-anchor" href="#how-they-interact" aria-label="Permalink to &quot;How they interact&quot;">​</a></h2><p>The three tools work in this order:</p><ol><li><strong>Filter</strong> decides which entries are included at all.</li><li><strong>Grouping</strong> bundles the remaining entries.</li><li><strong>Sorting</strong> orders within the groups.</li></ol><p>Sums and aggregates always relate to the <strong>filtered</strong> set.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/grids/suche">Search</a> — the difference between search and filter</li><li><a href="/en/ansichten/spalten-verwalten">Manage columns</a></li><li><a href="/en/referenz/filterbedingungen">Filter conditions</a></li><li><a href="/en/ansichten/ansicht-teilen">Sharing a view</a></li></ul>',52)])])}const u=t(a,[["render",n]]);export{p as __pageData,u as default};
